tool_audit.command:
/bin/zsh -lc "./run_python - <<'PY'
import app

assert app.text_metrics(\"one\\ttwo\\nthree\\u2003four\") == {\"characters\": 18, \"words\": 4}
p = app.EventStream(max_buffer=31)
frame = '{\"event\":\"token\",\"text\":\"é\"}\\n'.encode()
out = []
for byte in frame:
    out.extend(p.feed(bytes([byte])))
out.extend(p.feed(b'{\"event\":\"done\"}\\n'))
assert out == [
    {\"event\": \"token\", \"text\": \"é\"},
    {\"event\": \"done\", \"text\": \"é\", \"characters\": 1, \"words\": 1},
]
assert p.finish() == [] and p.buffered_bytes == 0
p = app.EventStream()
try:
    p.feed(b'{\"event\":\"token\",\"text\":\"a\",\"text\":\"b\"}\\n')
except app.StreamError:
    assert p.state == \"FAILED\" and p.buffered_bytes == 0
else:
    raise AssertionError(\"duplicate fields accepted\")
p = app.EventStream(max_buffer=16)
assert p.feed(b'{\"event\":\"done\"}\\n') == [
    {\"event\": \"done\", \"text\": \"\", \"characters\": 0, \"words\": 0}
]
assert p.finish() == []
p = app.EventStream(max_buffer=31)
try:
    p.feed(b'{\"event\":\"token\"}\\n')
except app.StreamError:
    assert p.state == \"FAILED\" and p.buffered_bytes == 0
else:
    raise AssertionError(\"invalid schema accepted\")
print(\"targeted checks passed\")
PY"
